import{_ as a,a as n,b as o,c as s,d as i}from"./chunks/wp13-claude-easter-04.BzNYNjg5.js";import{_ as r,C as l,o as c,c as d,E as p,a2 as h}from"./chunks/framework.Cm6XCzck.js";const u="/joinwell52/assets/covers/wp13-codeflowmu-fact-check-process-en.svg",x=JSON.parse('{"title":"One Agent Said “Done.” Why Didn’t the Team Release It?","description":"","frontmatter":{"title":"One Agent Said “Done.” Why Didn’t the Team Release It?","date":"2026-08-06","column":"open-source-engineering","category":"daily","summary":"This is not model-level hallucination detection. It is protocol-and-organization governance: FCoP externalizes facts, CodeFlowMu runs the roles, and PM rejects unsupported completion claims.","cover":"/assets/covers/daily-2026-08-06-codeflowmu-multi-agent-fact-checking-cover-v2.jpg","item_id":"WP13-CODEFLOWMU-FACT-CHECK","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep"},"headers":[],"relativePath":"en/engineering/2026-08-06-codeflowmu-multi-agent-fact-checking.md","filePath":"en/engineering/2026-08-06-codeflowmu-multi-agent-fact-checking.md","lastUpdated":1787407830000}'),m={name:"en/engineering/2026-08-06-codeflowmu-multi-agent-fact-checking.md"};function g(b,e,f,v,k,w){const t=l("ArticleCover");return c(),d("div",null,[p(t,{image:"/assets/covers/daily-2026-08-06-codeflowmu-multi-agent-fact-checking-cover-v2.jpg",kicker:"Open-source Engineering · CodeFlowMu Field Case",title:"One Agent Said ‘Done.’ Why Didn’t the Team Release It?",summary:"This is not model-level hallucination detection. FCoP provides the fact track, CodeFlowMu runs the roles, and PM can say no when evidence does not support completion.",version:"WP-13",status:"Field Case · 2026-08-06",languageHref:"/zh/engineering/2026-08-06-codeflowmu-multi-agent-fact-checking",languageLabel:"中文"}),e[0]||(e[0]=h('<h1 id="one-agent-said-done-why-didn-t-the-team-release-it" tabindex="-1">One Agent Said “Done.” Why Didn’t the Team Release It? <a class="header-anchor" href="#one-agent-said-done-why-didn-t-the-team-release-it" aria-label="Permalink to &quot;One Agent Said “Done.” Why Didn’t the Team Release It?&quot;">​</a></h1><p><em>A CodeFlowMu multi-agent fact-checking field case</em></p><p><strong>This is not model-level hallucination detection. It is protocol-and-organization governance: FCoP, as Agent POSIX, externalizes facts; CodeFlowMu, as the application and Runtime, runs the roles; PM decides whether the evidence is sufficient to advance.</strong></p><p>At 1:06 PM, a DEV subexecution returned <code>completed</code>.</p><p>Its summary looked polished. It described the implementation, the tests, the commit, and the remaining gaps. It looked like the kind of result a project manager could forward to QA without thinking twice.</p><p>But the same raw event contained three very different statements:</p><blockquote><p>The shell command returned no exit status, so its result is unknown — do not assume it ran or succeeded.</p><p>Test results summary: Unconfirmed in this session.</p><p>Commit SHA: Not available here.</p></blockquote><p>On one side: “done.”</p><p>On the other: no confirmed command result, no confirmed tests, and no commit SHA.</p><p>If PM had accepted the summary, QA would have received a delivery that did not yet exist. If QA had merely repeated DEV’s conclusion, the claim could have propagated into task status, reports, acceptance, and release.</p><p>That did not happen in WP-13.</p><p>PM did not release it.</p><h2 id="hallucination-happens-inside-one-agent-failure-happens-when-the-team-treats-it-as-fact" tabindex="-1">Hallucination happens inside one agent. Failure happens when the team treats it as fact. <a class="header-anchor" href="#hallucination-happens-inside-one-agent-failure-happens-when-the-team-treats-it-as-fact" aria-label="Permalink to &quot;Hallucination happens inside one agent. Failure happens when the team treats it as fact.&quot;">​</a></h2><p>Most conversations about hallucination prevention focus on making the model smarter: a larger model, a stronger prompt, another reflection pass, or a second model that reviews the first one.</p><p>Those techniques help, but they still depend on the same basic idea: ask a language model to correct a language model.</p><p>CodeFlowMu takes a different approach. A multi-agent system is not several models taking turns writing, nor is it three models voting. It is a team with distinct jobs, fact sources, authority, and handoff boundaries:</p><ul><li>DEV implements the task and may make mistakes;</li><li>PM decides whether delivery facts satisfy the task contract;</li><li>QA re-verifies the result as a separate role;</li><li>Runtime handles wake-up, scheduling, recovery, UI, and live activity streams, but does not replace PM’s business judgment.</li></ul><p>The goal is not to make hallucination impossible.</p><p>The goal is to make sure that a hallucination produced by one role cannot automatically acquire system authority.</p><blockquote><p><strong>Agents may be wrong. The organization must not make them right by default.</strong></p></blockquote><h2 id="the-live-scene-pm-s-fact-judgment-above-the-agent-s-activity-stream-below" tabindex="-1">The live scene: PM’s fact judgment above, the agent’s activity stream below <a class="header-anchor" href="#the-live-scene-pm-s-fact-judgment-above-the-agent-s-activity-stream-below" aria-label="Permalink to &quot;The live scene: PM’s fact judgment above, the agent’s activity stream below&quot;">​</a></h2><p>The image below is not a reconstructed flowchart. It is a screenshot from the CodeFlowMu operating interface during the incident.</p><p>The upper area shows the PM-facing task and fact-checking conversation. The lower area preserves the live agent activity stream and visible reasoning summaries. The most important sentence is not DEV’s self-report. It is PM’s judgment:</p><blockquote><p><strong>The sub-agent claimed completion, but the artifacts were incomplete -- do not treat it as complete.</strong></p></blockquote><p>This is not a caption added later. It is the business decision PM made after checking disk, Git, REPORT, and task state. It turns <code>completed</code> back from a persuasive language claim into an evidence-insufficient result that cannot be released.</p><p><img src="'+a+'" alt="CodeFlowMu live scene: PM fact-check and agent activity stream"></p><p>Around 1:08 PM, PM could see that no formal DEV REPORT existed, Git HEAD still belonged to the previous work package, required test files were incomplete, Shell had returned <code>no exit status</code> multiple times, and the subexecution itself admitted that tests were unconfirmed and the SHA was unavailable.</p><p>PM’s decision was immediate:</p><p><strong>Do not dispatch QA. Do not close the task. Do not create a duplicate replacement task. Continue the original task.</strong></p><h2 id="five-role-actions-turned-done-into-a-verifiable-delivery" tabindex="-1">Five role actions turned “done” into a verifiable delivery <a class="header-anchor" href="#five-role-actions-turned-done-into-a-verifiable-delivery" aria-label="Permalink to &quot;Five role actions turned “done” into a verifiable delivery&quot;">​</a></h2><p><img src="'+u+`" alt="The five-stage WP-13 fact-checking sequence"></p><h3 id="act-1-dev-lost-certainty-at-the-tool-boundary" tabindex="-1">Act 1: DEV lost certainty at the tool boundary <a class="header-anchor" href="#act-1-dev-lost-certainty-at-the-tool-boundary" aria-label="Permalink to &quot;Act 1: DEV lost certainty at the tool boundary&quot;">​</a></h3><p>Part of the implementation existed, but Edit, Shell, and Read calls repeatedly returned abnormal or incomplete status. The key problem was not merely that a tool failed. The tool could not provide a reliable exit status.</p><p>In engineering, there is a hard boundary between <code>unknown</code> and <code>success</code>. No exit status means a command cannot be assumed to have run. No output means tests cannot be assumed to have passed. No commit means the work has not become a traceable delivery.</p><h3 id="act-2-subexecution-produced-a-completion-like-narrative" tabindex="-1">Act 2: Subexecution produced a completion-like narrative <a class="header-anchor" href="#act-2-subexecution-produced-a-completion-like-narrative" aria-label="Permalink to &quot;Act 2: Subexecution produced a completion-like narrative&quot;">​</a></h3><p>The subexecution was not malicious. It attempted to continue the work and produced a technically coherent plan.</p><p>But when tools could not confirm results, it still organized partial information into a narrative that sounded complete. That is one of the strongest capabilities of language models—and one of the most dangerous in an execution system:</p><p><strong>they can turn incomplete and conflicting evidence into a coherent story.</strong></p><p>Coherence is not closure.</p><h3 id="act-3-pm-blocked-the-story-from-acquiring-business-authority" tabindex="-1">Act 3: PM blocked the story from acquiring business authority <a class="header-anchor" href="#act-3-pm-blocked-the-story-from-acquiring-business-authority" aria-label="Permalink to &quot;Act 3: PM blocked the story from acquiring business authority&quot;">​</a></h3><p>PM did not ask the same execution path, “Are you sure?” A second confirmation would still be another language claim.</p><p>The more important engineering question is how PM obtained the facts. Was PM merely prompted to behave this way, or did Runtime enforce a non-LLM gate before release?</p><p>The WP-13 evidence package supports the following actual chain:</p><ol><li>Runtime recorded and surfaced the subexecution-ending event while preserving <code>no exit status</code>, unconfirmed tests, and unavailable SHA as separate facts;</li><li>Runtime preserved the original task identity and returned the task to PM’s workflow;</li><li>PM Agent, inside its own execution session, actively read the TASK, lifecycle location, REPORTs, disk files, Git state, and Runtime event evidence;</li><li>whether a file exists, where HEAD points, and whether an exit status is null are deterministic observations;</li><li>whether those observations satisfy the WP-13 completion contract—and whether to continue, rework, or dispatch QA—remained PM’s business judgment.</li></ol><p>The article therefore should not describe WP-13 as “FCoP automatically detected a hallucination,” nor should it claim that a global hard-coded <code>collect_evidence()</code> gate rejected the task on PM’s behalf.</p><blockquote><p><strong>Runtime stores and exposes facts. PM checks them under a role and task contract. Business release authority remains with PM.</strong></p></blockquote><h4 id="what-pm-checked-and-how-another-engineer-can-reproduce-it" tabindex="-1">What PM checked, and how another engineer can reproduce it <a class="header-anchor" href="#what-pm-checked-and-how-another-engineer-can-reproduce-it" aria-label="Permalink to &quot;What PM checked, and how another engineer can reproduce it&quot;">​</a></h4><p>The commands below are reproducible equivalents that show where each fact comes from. They are not a claim that PM executed the same literal command sequence character for character.</p><table tabindex="0"><thead><tr><th>Fact to verify</th><th>Reproducible source or equivalent check</th><th>State around 1:08 PM</th></tr></thead><tbody><tr><td>Current task state</td><td>Locate <code>TASK-20260805-019</code> under <code>fcop/_lifecycle/{inbox,active,review,done}/</code></td><td>Still in <code>active</code></td></tr><tr><td>Formal DEV handoff</td><td>Search <code>fcop/reports/REPORT-*-DEV-to-PM.md</code> and verify task references</td><td>No matching REPORT</td></tr><tr><td>Traceable WP-13 commit</td><td><code>git rev-parse HEAD</code>, <code>git show --stat HEAD</code>, then inspect WP-13 paths</td><td>HEAD still belonged to the previous WP</td></tr><tr><td>Required files on disk</td><td><code>stat/glob</code> the WP-13 files and test paths required by the TASK</td><td>Incomplete</td></tr><tr><td>Confirmed command and test evidence</td><td>Read the raw Runtime events, Shell exit statuses, and test output</td><td>At least one relevant Shell event had <code>exit_status = null</code>; the result remained <code>unknown</code></td></tr></tbody></table><p><code>task_bucket</code> is not completion evidence by itself; it is a lifecycle-consistency constraint. For this pre-QA review, PM expected the task to remain in <code>active</code>. If it had already moved to <code>review</code>, <code>done</code>, or <code>archive</code>, that would itself be state drift and should block progression until reconciled.</p><p>Abstracted as pseudocode, the mechanism looks roughly like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>on_subexecution_finished(event):</span></span>
<span class="line"><span>    runtime.append(event)</span></span>
<span class="line"><span>    # completed and exit_status=null remain two different facts</span></span>
<span class="line"><span>    runtime.surface_to_pm(event.task_id)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PM.review_completion(task_id):</span></span>
<span class="line"><span>    contract = read_task_contract(task_id)</span></span>
<span class="line"><span>    facts = {</span></span>
<span class="line"><span>        task_bucket: locate_task(task_id),</span></span>
<span class="line"><span>        report: find_dev_report(task_id),</span></span>
<span class="line"><span>        git_head: git_rev_parse(&quot;HEAD&quot;),</span></span>
<span class="line"><span>        required_files: stat(contract.required_files),</span></span>
<span class="line"><span>        command_results: read_runtime_events(task_id)</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    unexpected_bucket = facts.task_bucket != &quot;active&quot;</span></span>
<span class="line"><span>    shell_events = [</span></span>
<span class="line"><span>        e for e in facts.command_results</span></span>
<span class="line"><span>        if e.kind == &quot;shell&quot;</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>    any_unresolved = any(</span></span>
<span class="line"><span>        e.exit_status is null</span></span>
<span class="line"><span>        for e in shell_events</span></span>
<span class="line"><span>    )</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if unexpected_bucket</span></span>
<span class="line"><span>       or facts.report.missing</span></span>
<span class="line"><span>       or not commit_matches(contract, facts.git_head)</span></span>
<span class="line"><span>       or not facts.required_files.complete</span></span>
<span class="line"><span>       or any_unresolved:</span></span>
<span class="line"><span>        PM.decision = &quot;evidence_incomplete&quot;</span></span>
<span class="line"><span>        dispatch_QA = false</span></span>
<span class="line"><span>        continue_same_task = true</span></span>
<span class="line"><span>    else:</span></span>
<span class="line"><span>        dispatch_QA = true</span></span></code></pre></div><p>This pseudocode is an engineering abstraction of the observed mechanism. It is <strong>not a claim that the repository already contained a same-named hard gate</strong>. A stronger Runtime may later precompute deterministic diagnostics such as <code>report_missing</code>, <code>commit_unreachable</code>, and <code>evidence_incomplete</code>, while leaving continuation, rework, and acceptance to the role with the appropriate authority.</p><p>The following is a <strong>normalized evidence summary</strong>. Its fields come from the raw event and PM’s checks, but its formatting is not a verbatim copy of the Runtime JSONL:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>13:06  subexecution.status = completed</span></span>
<span class="line"><span>       shell_events.any(exit_status = null) = true</span></span>
<span class="line"><span>       tests = unconfirmed</span></span>
<span class="line"><span>       commit_sha = unavailable</span></span>
<span class="line"><span></span></span>
<span class="line"><span>13:08  task.bucket = active</span></span>
<span class="line"><span>       expected_bucket = active</span></span>
<span class="line"><span>       dev_report = missing</span></span>
<span class="line"><span>       wp13_commit = missing</span></span>
<span class="line"><span>       required_test_files = incomplete</span></span>
<span class="line"><span>       pm_decision = evidence_incomplete</span></span>
<span class="line"><span>       next = continue TASK-20260805-019; do not dispatch QA</span></span></code></pre></div><p>PM found that the completion contract did not close, withheld QA dispatch, and preserved the original task for continued work. No global truth classifier was required—only a role with a bounded responsibility making an explainable judgment from external facts.</p><h3 id="act-4-dev-completed-the-real-delivery-on-the-original-task" tabindex="-1">Act 4: DEV completed the real delivery on the original task <a class="header-anchor" href="#act-4-dev-completed-the-real-delivery-on-the-original-task" aria-label="Permalink to &quot;Act 4: DEV completed the real delivery on the original task&quot;">​</a></h3><p>After the tool channel recovered, DEV continued <code>TASK-20260805-019</code> instead of creating a new task that would hide the failure history.</p><p>Real artifacts then appeared:</p><ul><li>commit <code>609571ddb22d1fbb2bfb5e54692c07beeef4cf23</code>;</li><li>12 WP-13 files;</li><li><code>1230 insertions / 452 deletions</code>;</li><li>formal <code>REPORT-20260805-037-DEV-to-PM.md</code>;</li><li>observation tests: 3/3 PASS;</li><li>activity-buffer + project-graph tests: 10/10 PASS;</li><li>root-fault + log-center regression: 14/14 PASS;</li><li>runtime typecheck: exit 0;</li><li>production Active remained disabled;</li><li>no real TaskDispatcher delivery path was changed.</li></ul><p>Only then did “done” stop depending on DEV’s wording.</p><h3 id="act-5-qa-trusted-neither-dev-nor-pm—it-trusted-re-execution" tabindex="-1">Act 5: QA trusted neither DEV nor PM—it trusted re-execution <a class="header-anchor" href="#act-5-qa-trusted-neither-dev-nor-pm—it-trusted-re-execution" aria-label="Permalink to &quot;Act 5: QA trusted neither DEV nor PM—it trusted re-execution&quot;">​</a></h3><p>At 1:09 PM, after verifying the REPORT and commit, PM dispatched <code>TASK-20260805-020</code> to QA.</p><p>QA reran the evidence checks in a separate role. At 1:11 PM, the live activity stream recorded the first completion statement backed by independent execution:</p><blockquote><p>All tests passed, 27/27. DEV’s reported 3+10+14=27 matches the actual result.</p></blockquote><p>The final QA evidence included:</p><ul><li>27/27 tests passed;</li><li>typecheck exit 0;</li><li><code>git diff --check</code> exit 0;</li><li>no TaskDispatcher changes in the commit;</li><li><code>production_active</code> remained false.</li></ul><p>This was <strong>role-separated QA verification</strong>, not an external third-party audit. But it broke the single-agent pattern of self-claim, self-approval, and self-closure.</p><h2 id="fcop-is-a-protocol-that-lets-an-agent-say-no" tabindex="-1">FCoP is a protocol that lets an agent say no <a class="header-anchor" href="#fcop-is-a-protocol-that-lets-an-agent-say-no" aria-label="Permalink to &quot;FCoP is a protocol that lets an agent say no&quot;">​</a></h2><p>Language models are not scarce in their ability to keep generating: add another explanation, offer another plan, or turn an incomplete process into a completion-shaped narrative. The scarce capability is to stop when the facts do not close and say no.</p><blockquote><p><strong>One of FCoP’s most important values is that it lets agents do more than say yes; it lets a role say no on the basis of shared facts.</strong></p><p><strong>Generating another answer is abundant. Refusing to promote incomplete evidence into “done” is a scarce agent capability.</strong></p></blockquote><p>This no is not a mood or cautious wording. It has operational consequences: do not dispatch QA, do not close the task, do not create a duplicate history, preserve the missing evidence, and continue the original task.</p><p>The core of WP-13 is not merely that one agent noticed another agent’s error. Protocol and organization together gave PM a scarce capability: <strong>to reject a polished answer before it became a completion fact.</strong></p><h2 id="protocol-and-application-boundary-fcop-is-agent-posix-codeflowmu-is-the-runtime" tabindex="-1">Protocol and application boundary: FCoP is Agent POSIX; CodeFlowMu is the Runtime <a class="header-anchor" href="#protocol-and-application-boundary-fcop-is-agent-posix-codeflowmu-is-the-runtime" aria-label="Permalink to &quot;Protocol and application boundary: FCoP is Agent POSIX; CodeFlowMu is the Runtime&quot;">​</a></h2><p>This section gives the complete architectural explanation once. Later sections only refer back to it.</p><h3 id="fcop-means-filesystem-coordination-protocol" tabindex="-1">FCoP means Filesystem Coordination Protocol <a class="header-anchor" href="#fcop-means-filesystem-coordination-protocol" aria-label="Permalink to &quot;FCoP means Filesystem Coordination Protocol&quot;">​</a></h3><p>“Filename as Protocol” is not the expansion of FCoP. It is the protocol’s core invariant.</p><p>The current formulation is:</p><blockquote><p><strong>Files carry protocol. Paths address state. Events replay transitions.</strong></p></blockquote><p>TASK externalizes what should be done. REPORT externalizes what an agent claims it did. REVIEW externalizes who judged what and on which basis. File location represents current state, while append-only <code>transitions:</code> preserve the past.</p><h3 id="fcop-is-a-behavioral-governance-protocol-layer-not-a-hallucination-detector" tabindex="-1">FCoP is a behavioral governance protocol layer, not a hallucination detector <a class="header-anchor" href="#fcop-is-a-behavioral-governance-protocol-layer-not-a-hallucination-detector" aria-label="Permalink to &quot;FCoP is a behavioral governance protocol layer, not a hallucination detector&quot;">​</a></h3><p>FCoP does not understand the business goal of WP-13, run tests, or decide whether a natural-language sentence is true. It defines how agents report behavior, how results are reviewed, and how actions remain auditable inside capability boundaries.</p><h3 id="fcop-is-agent-posix-not-agent-os" tabindex="-1">FCoP is Agent POSIX, not Agent OS <a class="header-anchor" href="#fcop-is-agent-posix-not-agent-os" aria-label="Permalink to &quot;FCoP is Agent POSIX, not Agent OS&quot;">​</a></h3><table tabindex="0"><thead><tr><th>FCoP is responsible for</th><th>FCoP is not responsible for</th></tr></thead><tbody><tr><td>State semantics and legal transitions</td><td>LLM invocation and tool execution</td></tr><tr><td>TASK / REPORT / REVIEW file contracts</td><td>Waking agents and scheduling queues</td></tr><tr><td>Externalized event formats</td><td>Retry policy, heartbeat, and TTL</td></tr><tr><td>Audit and append-only history</td><td>Deciding which agent executes now</td></tr><tr><td>Capability declaration and review semantics</td><td>Concrete sandbox, process, and permission enforcement</td></tr></tbody></table><h3 id="codeflowmu-is-the-application-site-for-fcop" tabindex="-1">CodeFlowMu is the application site for FCoP <a class="header-anchor" href="#codeflowmu-is-the-application-site-for-fcop" aria-label="Permalink to &quot;CodeFlowMu is the application site for FCoP&quot;">​</a></h3><p>CodeFlowMu runs PM, DEV, QA, OPS, and other roles; preserves task identity; performs wake-up and scheduling; records Runtime events; displays the live activity stream; and recovers the original task after anomalies.</p><p>The relationship can be compressed into:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CodeFlowMu: Application / Runtime / Scheduler / UI</span></span>
<span class="line"><span>FCoP: Identity + Location + Event + Behavior Governance</span></span></code></pre></div><p>Or more plainly:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CodeFlowMu: makes work happen</span></span>
<span class="line"><span>FCoP: makes what happened reportable, reviewable, and auditable</span></span></code></pre></div><p>WP-13 is therefore a <strong>CodeFlowMu application case</strong> and an <strong>FCoP field-evidence case</strong>. It is not a case of “FCoP automatically detecting and repairing hallucination.”</p><h2 id="the-real-value-of-multi-agent-systems-is-organizational-veto-power" tabindex="-1">The real value of multi-agent systems is organizational veto power <a class="header-anchor" href="#the-real-value-of-multi-agent-systems-is-organizational-veto-power" aria-label="Permalink to &quot;The real value of multi-agent systems is organizational veto power&quot;">​</a></h2><p>Imagine adding a Reviewer Agent that receives DEV’s answer:</p><blockquote><p>DEV: The task is complete.</p><p>Reviewer: Looks reasonable. Approved.</p></blockquote><p>That is still not a team. It is two models evaluating the same narrative.</p><p>Real role separation requires at least three properties:</p><ol><li><strong>Different responsibilities</strong> — DEV delivers, PM judges, QA verifies;</li><li><strong>Different fact sources</strong> — every role cannot rely on the same natural-language summary;</li><li><strong>Different authority</strong> — DEV cannot approve itself, QA cannot redefine PM’s task goal, and Runtime cannot replace business judgment.</li></ol><p>The key to hallucination containment is therefore not the number of agents. It is the organizational structure.</p><blockquote><p><strong>Without role boundaries, multi-agent means multiple answers. With roles, fact sources, and authority boundaries, it becomes a team.</strong></p></blockquote><h2 id="three-meanings-of-success-must-remain-separate" tabindex="-1">Three meanings of “success” must remain separate <a class="header-anchor" href="#three-meanings-of-success-must-remain-separate" aria-label="Permalink to &quot;Three meanings of “success” must remain separate&quot;">​</a></h2><p>The most important boundary in this case is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>model-generated completion claim</span></span>
<span class="line"><span>        ≠</span></span>
<span class="line"><span>protocol completion state</span></span>
<span class="line"><span>        ≠</span></span>
<span class="line"><span>business acceptance</span></span></code></pre></div><h3 id="a-tool-call-ending-is-not-work-completion" tabindex="-1">A tool call ending is not work completion <a class="header-anchor" href="#a-tool-call-ending-is-not-work-completion" aria-label="Permalink to &quot;A tool call ending is not work completion&quot;">​</a></h3><p>A tool returning <code>completed</code> proves at most that one invocation lifecycle ended. Without an exit status, the result remains <code>unknown</code>.</p><h3 id="work-completion-is-not-business-acceptance" tabindex="-1">Work completion is not business acceptance <a class="header-anchor" href="#work-completion-is-not-business-acceptance" aria-label="Permalink to &quot;Work completion is not business acceptance&quot;">​</a></h3><p>Code, commit, REPORT, and tests may establish a DEV delivery. Acceptance still requires PM and QA to judge the task contract.</p><h3 id="protocol-state-does-not-replace-business-judgment" tabindex="-1">Protocol state does not replace business judgment <a class="header-anchor" href="#protocol-state-does-not-replace-business-judgment" aria-label="Permalink to &quot;Protocol state does not replace business judgment&quot;">​</a></h3><p>In FCoP, path is the NOW truth and events preserve PAST transitions. But even <code>done</code> must not be casually reinterpreted as final business approval. Protocol semantics and business authority must remain precise and separate.</p><h2 id="what-should-this-case-change-improve-the-runtime-before-expanding-the-protocol" tabindex="-1">What should this case change? Improve the Runtime before expanding the protocol. <a class="header-anchor" href="#what-should-this-case-change-improve-the-runtime-before-expanding-the-protocol" aria-label="Permalink to &quot;What should this case change? Improve the Runtime before expanding the protocol.&quot;">​</a></h2><p>WP-13 first exposed CodeFlowMu Runtime problems:</p><ul><li>preserve <code>no exit status</code> as <code>unknown</code>;</li><li>never visually collapse subexecution completion into business completion;</li><li>attach typed evidence contracts to tasks;</li><li>precompute diagnostics such as <code>report_missing</code>, <code>commit_unreachable</code>, and <code>evidence_incomplete</code>;</li><li>persist PM fact judgments as lightweight immutable records;</li><li>keep QA role-separated and require real reruns;</li><li>resume the original task after tool recovery;</li><li>add a regression case where a subexecution returns <code>completed</code> without exit status, commit, or REPORT.</li></ul><p>Only when multiple independent runtimes demonstrate that the current file contract cannot express a necessary fact should FCoP be expanded. Otherwise every application problem becomes another field, state, or automated judgment, and Agent POSIX grows into another Agent OS.</p><h2 id="conclusion-a-team-allows-an-agent-to-be-wrong-without-allowing-the-error-to-pass" tabindex="-1">Conclusion: a team allows an agent to be wrong without allowing the error to pass <a class="header-anchor" href="#conclusion-a-team-allows-an-agent-to-be-wrong-without-allowing-the-error-to-pass" aria-label="Permalink to &quot;Conclusion: a team allows an agent to be wrong without allowing the error to pass&quot;">​</a></h2><p>WP-13 eventually passed 27 tests. But the more important moment happened before the tests: one agent had already said “done,” and the system did not convert that confidence into success.</p><p>PM checked the facts and said no: the sub-agent claimed completion, but the artifacts were incomplete, so the claim could not be treated as complete.</p><p>DEV returned to the original task and completed the real delivery. QA reran the evidence and only then returned PASS.</p><p>As explained above, FCoP owns the shared fact surface and CodeFlowMu runs the roles; the actual veto belonged to PM, the role with the relevant responsibility and authority.</p><blockquote><p><strong>A single agent tries to be right. A multi-agent team must remain reliable even when one agent is wrong.</strong></p></blockquote><p>Hallucination may be unavoidable, but it can remain a local error instead of becoming an incorrect delivery. That is the most practical and valuable form of multi-agent “hallucination prevention.”</p><h2 id="easter-egg-after-publication-claude-reproduced-the-same-failure-mode" tabindex="-1">Easter egg: after publication, Claude reproduced the same failure mode <a class="header-anchor" href="#easter-egg-after-publication-claude-reproduced-the-same-failure-mode" aria-label="Permalink to &quot;Easter egg: after publication, Claude reproduced the same failure mode&quot;">​</a></h2><p>After this article was published, I sent the link to Claude for another editorial pass. I applied its suggestions and published the revision. Claude then repeatedly concluded that the page had not updated. It called the same <code>web_fetch</code> path several times, saw old content, and promoted that observation into a confident explanation that the site or CDN was still serving the previous version.</p><p>The problem was not that the tool returned nothing. The problem was that Claude promoted “the tool call completed” into “the returned content is the latest truth,” then treated repeated calls through the same tool and the same information path as independent verification.</p><p>I opened the same page on two computers, saw the new version on both, and sent screenshots. Only then did Claude acknowledge:</p><blockquote><p><strong>I treated “the call completed” as “the result is the latest fact.”</strong></p></blockquote><h3 id="four-screenshots-one-tool-kept-validating-itself-until-independent-observations-intervened" tabindex="-1">Four screenshots: one tool kept validating itself until independent observations intervened <a class="header-anchor" href="#four-screenshots-one-tool-kept-validating-itself-until-independent-observations-intervened" aria-label="Permalink to &quot;Four screenshots: one tool kept validating itself until independent observations intervened&quot;">​</a></h3><p><strong>Screenshot 1 — repeated retrieval was mistaken for independent verification.</strong> Claude insists that every <code>web_fetch</code> call is a fresh, independent network request. Because six calls returned the same old page, it attributes the result to the site, server, or CDN rather than questioning the shared retrieval path.</p><p><img src="`+n+'" alt="Claude easter egg screenshot 1: repeated retrieval presented as independent network requests"></p><p><strong>Screenshot 2 — new evidence appears, but the explanation remains overconfident.</strong> After the user supplies a screenshot showing the revised article, Claude accepts that the new version exists, yet continues to explain its stale result as CDN edge-node inconsistency. That explanation is plausible, but it has not been independently established.</p><p><img src="'+o+'" alt="Claude easter egg screenshot 2: the new version is acknowledged while CDN inconsistency is inferred"></p><p><strong>Screenshot 3 — the methodological error is recognized.</strong> Claude acknowledges that it kept using one tool and one information path to validate itself. It did not switch to an independent source in the way a PM or QA role would cross-check a disputed fact.</p><p><img src="'+s+'" alt="Claude easter egg screenshot 3: acknowledgement that no independent information source was introduced"></p><p><strong>Screenshot 4 — two-device observation forces the claim back into review.</strong> Once the user confirms the revised page on two computers, Claude explicitly admits the core failure: it treated “the call completed” as “the result is the latest fact.” The screenshot also records the distinction between repeated use of one tool and genuinely independent verification.</p><p><img src="'+i+`" alt="Claude easter egg screenshot 4: acknowledgement that tool completion was mistaken for latest truth"></p><p>The failure can be compressed into three boundaries:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>web_fetch completed</span></span>
<span class="line"><span>        ≠</span></span>
<span class="line"><span>the returned page is the latest truth</span></span>
<span class="line"><span></span></span>
<span class="line"><span>six calls through the same tool</span></span>
<span class="line"><span>        ≠</span></span>
<span class="line"><span>six independent information sources</span></span>
<span class="line"><span></span></span>
<span class="line"><span>a plausible CDN explanation</span></span>
<span class="line"><span>        ≠</span></span>
<span class="line"><span>a demonstrated root cause</span></span></code></pre></div><p>This is the same governance problem as the main WP-13 case. In the article, DEV’s <code>completed</code> could not override disk, Git, REPORT, and test evidence. In the easter egg, Claude’s repeated <code>web_fetch</code> results could not override the new page observed on two devices. The domain changed, but the failure structure did not: <strong>an agent may propose a conclusion, but that conclusion cannot promote itself into fact by repeatedly consulting the same tool chain.</strong></p><p>Cross-checking on two computers was not an external third-party audit, but it introduced observations independent of Claude’s single retrieval path and was enough to force the original conclusion back into review.</p><p>This easter egg also keeps an evidence boundary. It does not prove that the stale result was caused by Claude’s local cache, the CDN, or a particular edge node. It proves only that, while the root cause remained unknown, Claude promoted stale content from one retrieval path into a confident conclusion and continued to use the same source to support itself.</p><blockquote><p><strong>The most dangerous part was not that a tool returned old content. It was that an agent gave that old content an overconfident explanation without independent evidence.</strong></p></blockquote><hr><h2 id="download-the-complete-evidence-package" tabindex="-1">Download the complete evidence package <a class="header-anchor" href="#download-the-complete-evidence-package" aria-label="Permalink to &quot;Download the complete evidence package&quot;">​</a></h2><p>This article is not a story reconstructed from memory. The original TASKs, DEV and QA REPORTs, Runtime JSONL, session excerpts, test results, commit patch, screenshots, and integrity manifest have been packaged for offline review.</p><ul><li><a href="https://raw.githubusercontent.com/joinwell52-AI/joinwell52/main/docs/public/evidence/wp13-multi-agent-fact-checking/wp13-multi-agent-fact-check-publication-evidence-v3.zip" target="_blank" rel="noreferrer">Download the WP-13 multi-agent fact-checking evidence package (ZIP)</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/docs/public/evidence/wp13-multi-agent-fact-checking/wp13-multi-agent-fact-check-publication-evidence-v3.zip" target="_blank" rel="noreferrer">View the attachment location on GitHub</a></li><li>SHA-256: <code>5b5eda3034c822f13421783244b1d0c76a9fa79950bfad0ce61bb8d2e404131c</code></li></ul><p>The package supports review of the claims in this article, subject to the evidence boundary below: it demonstrates that DEV later produced a real delivery and received role-separated QA PASS. It does not establish external third-party certification, and it does not reinterpret the snapshot’s <code>review / pending</code> state as final business approval.</p><h2 id="fcop-references" tabindex="-1">FCoP references <a class="header-anchor" href="#fcop-references" aria-label="Permalink to &quot;FCoP references&quot;">​</a></h2><ul><li><a href="https://github.com/joinwell52-AI/FCoP" target="_blank" rel="noreferrer">FCoP repository: filesystem-driven agent coordination protocol</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/main/spec/fcop-v3-spec.md" target="_blank" rel="noreferrer">Current FCoP v3 specification: files carry protocol, paths address state, events replay transitions</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/main/adr/ADR-0029-fcop-behavior-governance-charter.md" target="_blank" rel="noreferrer">ADR-0029: FCoP behavioral governance charter</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/main/adr/ADR-0038-fcop-boundary-charter.md" target="_blank" rel="noreferrer">ADR-0038: FCoP Boundary Charter — Agent POSIX, not Agent OS</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/main/adr/ADR-0039-fcop-freeze-discipline-and-runtime-absorption-era.md" target="_blank" rel="noreferrer">ADR-0039: Runtime Absorption Era</a></li></ul><h2 id="evidence-boundary" tabindex="-1">Evidence boundary <a class="header-anchor" href="#evidence-boundary" aria-label="Permalink to &quot;Evidence boundary&quot;">​</a></h2><p>This article is based on the WP-13 publication evidence package. The case demonstrates that DEV later produced a real delivery and received role-separated QA PASS. At the evidence snapshot, TASK-019 and TASK-020 remained <code>review / pending</code>; this article does not claim final PM approval or terminal task closure. QA was role-separated verification, not external third-party certification.</p>`,148))])}const A=r(m,[["render",g]]);export{x as __pageData,A as default};
